// Strict CLDR49 collation rule parser. Intermediate AST only, not production CE data.
// Unsupported XML/rule constructs fail instead of selecting root silently.
#include <algorithm>
#include <cctype>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <map>
#include <set>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
namespace fs=std::filesystem;
[[noreturn]] void bad(const std::string&s){throw std::runtime_error(s);}
std::string trim(std::string s){auto a=s.find_first_not_of(" \t\r\n");return a==s.npos?"":s.substr(a,s.find_last_not_of(" \t\r\n")-a+1);}
std::string load(const fs::path&p){std::ifstream f(p,std::ios::binary);std::ostringstream s;s<<f.rdbuf();if(!f)bad("read "+p.string());return s.str();}
struct Rule {int op=0,strength=0,before=0;bool starred=false;std::string text,prefix,extension;};
struct Tailoring {std::string locale,type,variant,default_type,source_rules;std::vector<Rule> rules;};
struct Parser {
 std::string s;std::size_t p=0;std::vector<Rule> rules;bool anchor=false;
 explicit Parser(std::string text):s(std::move(text)){}
 std::size_t white()const{if(p>=s.size())return 0;unsigned char c=s[p];if(c==9||c==10||c==11||c==12||c==13||c==32)return 1;if(c==194&&p+1<s.size()&&static_cast<unsigned char>(s[p+1])==133)return 2;if(c==226&&p+2<s.size()&&static_cast<unsigned char>(s[p+1])==128){auto last=static_cast<unsigned char>(s[p+2]);if(last==142||last==143||last==168||last==169)return 3;}return 0;}
 void skip(){while(p<s.size()){if(auto n=white()){p+=n;continue;}if(s[p]=='#'){while(p<s.size()&&s[p]!='\n')++p;continue;}break;}}
 std::string bracket(){if(p==s.size()||s[p]!='[')bad("expected bracket");std::size_t start=++p;int depth=1;bool quote=false;while(p<s.size()){char c=s[p++];if(c=='\\'){if(p==s.size())bad("bracket escape");++p;continue;}if(c=='\'')quote=!quote;if(!quote){if(c=='[')++depth;if(c==']'&&!--depth)return trim(s.substr(start,p-start-1));}}bad("unclosed bracket");}
 static bool special(char c){return c=='&'||c=='<'||c=='='||c==';'||c==','||c=='['||c==']'||c=='!'||c=='@';}
 std::string literal(){std::string out;bool quoted=false;while(p<s.size()){char c=s[p];if(c=='\''){++p;if(p<s.size()&&s[p]=='\''){out.push_back('\'');++p;continue;}quoted=!quoted;continue;}if(c=='\\'){out.push_back(c);++p;if(p==s.size())bad("literal escape");char kind=s[p++];if(kind=='|'||kind=='/'||kind=='-'){out.pop_back();const char*digits="0123456789ABCDEF";out+="\\u00";out.push_back(digits[(static_cast<unsigned char>(kind)>>4)&15]);out.push_back(digits[static_cast<unsigned char>(kind)&15]);continue;}out.push_back(kind);int n=kind=='u'?4:kind=='U'?8:0;for(int i=0;i<n;++i){if(p==s.size()||!std::isxdigit(static_cast<unsigned char>(s[p])))bad("Unicode escape digits");out.push_back(s[p++]);}continue;}if(!quoted&&(special(c)||c=='#'))break;if(!quoted&&white())break;if(quoted&&(c=='/'||c=='|'||c=='-'||c=='['||c==']')){const char*digits="0123456789ABCDEF";out+="\\u00";out.push_back(digits[(static_cast<unsigned char>(c)>>4)&15]);out.push_back(digits[static_cast<unsigned char>(c)&15]);}else out.push_back(c);++p;}if(quoted)bad("unclosed rule quote");return out;}
 void split_relation(Rule&r){auto bar=r.text.find('|');if(bar!=r.text.npos){if(r.text.find('|',bar+1)!=r.text.npos)bad("multiple prefix separators");r.prefix=r.text.substr(0,bar);r.text.erase(0,bar+1);}auto slash=r.text.find('/');if(slash!=r.text.npos){if(r.text.find('/',slash+1)!=r.text.npos)bad("multiple expansion separators");r.extension=r.text.substr(slash+1);r.text.resize(slash);if(r.extension.empty())bad("empty expansion");}if(r.text.empty())bad("empty relation");}
 void parse(){while(true){skip();if(p==s.size())break;char c=s[p];
  if(c=='['){auto option=bracket();std::istringstream words(option);std::string name;words>>name;static const std::set<std::string> known={"alternate","backwards","caseFirst","caseLevel","strength","normalization","numericOrdering","reorder","maxVariable","import","optimize","suppressContractions"};if(!known.contains(name))bad("unsupported setting ["+option+"]");std::string value=trim(option.substr(name.size()));static const std::map<std::string,std::set<std::string>> values={{"alternate",{"shifted","non-ignorable"}},{"backwards",{"2"}},{"caseFirst",{"off","lower","upper"}},{"caseLevel",{"off","on"}},{"strength",{"1","2","3","4","I"}},{"normalization",{"off","on"}},{"numericOrdering",{"off","on"}},{"maxVariable",{"space","punct","symbol","currency"}}};if(auto v=values.find(name);v!=values.end()&&!v->second.contains(value))bad("unsupported setting value ["+option+"]");if(value.empty())bad("empty setting value");if((name=="optimize"||name=="suppressContractions")&&(value.front()!='['||value.back()!=']'))bad("expected UnicodeSet");Rule r;r.op=name=="import"?4:3;r.text=option;rules.push_back(std::move(r));continue;}
  if(c=='&'){++p;skip();Rule r;r.op=1;if(p<s.size()&&s[p]=='['){auto special=bracket();if(special.starts_with("before ")){if(special.size()!=8||special[7]<'1'||special[7]>'3')bad("before strength");r.before=special[7]-'0';skip();if(p<s.size()&&s[p]=='[')r.text="["+bracket()+"]";else r.text=literal();}else r.text="["+special+"]";}else r.text=literal();if(r.text.empty())bad("empty reset");rules.push_back(std::move(r));anchor=true;continue;}
  Rule r;r.op=2;if(!anchor)bad("relation without reset");if(c=='<'){while(p<s.size()&&s[p]=='<'){++r.strength;++p;}if(r.strength>4)bad("relation strength");}else if(c=='='){++p;r.strength=0;}else if(c==';'){++p;r.strength=2;}else if(c==','){++p;r.strength=3;}else bad("unsupported rule token at "+std::to_string(p)+": "+s.substr(p,50));
  skip();if(p<s.size()&&s[p]=='*'){r.starred=true;++p;}r.text=literal();split_relation(r);rules.push_back(std::move(r));
 }}
};
std::map<std::string,std::string> attrs(const std::string&s){std::map<std::string,std::string> result;std::size_t p=0;while(p<s.size()&&!std::isspace(static_cast<unsigned char>(s[p])))++p;while(p<s.size()){while(p<s.size()&&(std::isspace(static_cast<unsigned char>(s[p]))||s[p]=='/'))++p;if(p==s.size())break;auto start=p;while(p<s.size()&&(std::isalnum(static_cast<unsigned char>(s[p]))||s[p]=='_'||s[p]=='-'))++p;if(start==p)bad("attribute name");auto name=s.substr(start,p-start);while(p<s.size()&&std::isspace(static_cast<unsigned char>(s[p])))++p;if(p==s.size()||s[p++]!='=')bad("attribute equals");while(p<s.size()&&std::isspace(static_cast<unsigned char>(s[p])))++p;if(p==s.size()||(s[p]!='\''&&s[p]!='"'))bad("attribute quote");char q=s[p++];start=p;auto end=s.find(q,p);if(end==s.npos)bad("attribute close");if(!result.emplace(name,s.substr(start,end-start)).second)bad("duplicate attr");p=end+1;}return result;}
std::vector<Tailoring> xml(const fs::path&path){auto s=load(path);std::vector<Tailoring> out;std::vector<std::string> stack;std::size_t p=0;Tailoring current;bool inside=false;std::string default_type="standard";while(p<s.size()){auto start=s.find('<',p);if(start==s.npos)break;if(s.compare(start,4,"<!--")==0){auto end=s.find("-->",start+4);if(end==s.npos)bad("XML comment");p=end+3;continue;}if(s.compare(start,9,"<![CDATA[")==0){auto end=s.find("]]>",start+9);if(end==s.npos)bad("XML CDATA");if(stack.empty()||stack.back()!="cr"||!inside)bad("unexpected CDATA");current.source_rules+=s.substr(start+9,end-start-9)+"\n";Parser parser(s.substr(start+9,end-start-9));try{parser.parse();}catch(const std::exception&e){bad(path.filename().string()+"/"+current.type+": "+e.what());}current.rules.insert(current.rules.end(),parser.rules.begin(),parser.rules.end());p=end+3;continue;}auto end=s.find('>',start+1);if(end==s.npos)bad("XML tag");auto token=trim(s.substr(start+1,end-start-1));p=end+1;if(token.starts_with("?")||token.starts_with("!DOCTYPE"))continue;bool close=token.starts_with("/"),self=token.ends_with("/");if(close)token.erase(0,1);if(self)token.pop_back();auto name=token.substr(0,token.find_first_of(" \t\r\n"));if(close){if(stack.empty()||stack.back()!=name)bad("XML nesting "+name);stack.pop_back();if(name=="collation"){out.push_back(current);inside=false;}continue;}static const std::set<std::string> known={"ldml","identity","version","language","script","territory","variant","collations","collation","defaultCollation","cr"};if(!known.contains(name))bad("unsupported XML element "+name);if(name=="defaultCollation"){auto finish=s.find("</defaultCollation>",p);if(finish==s.npos)bad("default collation text");default_type=trim(s.substr(p,finish-p));if(default_type.empty())bad("empty default collation");}if(name=="collation"){if(inside)bad("nested collation");auto a=attrs(token);if(!a.contains("type"))bad("collation type");current={path.stem().string(),a.at("type"),a.contains("alt")?a.at("alt"):"",default_type,"",{}};inside=true;if(self){out.push_back(current);inside=false;}}if(!self)stack.push_back(name);}if(!stack.empty()||inside)bad("XML unclosed");return out;}
void controls(){
 Parser p("&a<'|'<<b/c<<<p|q<*'-'-'/'<\\|");p.parse();if(p.rules.size()!=6||p.rules[1].text!="\\u007C"||!p.rules[1].prefix.empty()||p.rules[2].extension!="c"||p.rules[3].prefix!="p"||p.rules[3].text!="q"||!p.rules[4].starred||p.rules[4].text!="\\u002D-\\u002F"||p.rules[5].text!="\\u007C")bad("quoted/escaped separator control");
 for(const auto&invalid:{"&a b<c","[unknown on]","[strength magic]","&a<<<<<<b","&a<'unclosed","&a<\\u00ZZ","&a<<b/","[import]","&[before 4]a<b"}){bool rejected=false;try{Parser wrong(invalid);wrong.parse();}catch(const std::exception&){rejected=true;}if(!rejected)bad(std::string("wrong grammar accepted: ")+invalid);}
 Parser bracket("&\'[\'<x");bracket.parse();if(bracket.rules.size()!=2||bracket.rules[0].text!="\\u005B")bad("quoted reset bracket");
 std::cout<<"CLDR_PARSER_CONTROLS_OK quoted_and_escaped_separators bad_grammar_rejected\n";
}
#ifndef SOUNIO_CLDR_NO_MAIN
int main(int argc,char**argv){try{if(argc!=3){std::cerr<<"usage: cldr_generate CLDR49_SELECTED_ROOT INVENTORY.tsv\n";return 64;}controls();fs::path root=argv[1];auto dtd=load(root/"common/dtd/ldml.dtd");std::string compact;for(unsigned char c:dtd)if(!std::isspace(c))compact.push_back(c);if(compact.find("cldrVersionCDATA#FIXED\"49\"")==compact.npos)bad("expected CLDR49");std::vector<fs::path> files;for(const auto&e:fs::directory_iterator(root/"common/collation"))if(e.path().extension()==".xml")files.push_back(e.path());std::sort(files.begin(),files.end());if(files.empty())bad("empty registry");std::ofstream report(argv[2]);if(!report)bad("report open");report<<"locale\ttype\talt\tdefault_type\tresets\trelations\tstarred\tprefix\texpansion\tsettings\timports\n";std::uint64_t count=0;for(const auto&p:files)for(const auto&t:xml(p)){std::uint64_t reset=0,relation=0,star=0,prefix=0,expansion=0,setting=0,imports=0;for(const auto&r:t.rules){reset+=r.op==1;relation+=r.op==2;setting+=r.op==3;imports+=r.op==4;star+=r.starred;prefix+=!r.prefix.empty();expansion+=!r.extension.empty();}report<<t.locale<<'\t'<<t.type<<'\t'<<t.variant<<'\t'<<t.default_type<<'\t'<<reset<<'\t'<<relation<<'\t'<<star<<'\t'<<prefix<<'\t'<<expansion<<'\t'<<setting<<'\t'<<imports<<'\n';++count;}if(!report)bad("report write");std::cout<<"CLDR_RULE_PARSE_OK files="<<files.size()<<" tailorings="<<count<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"CLDR_RULE_PARSE_ERROR "<<e.what()<<"\n";return 1;}}

#endif
